			inc hl
			ld d, (hl)
			ld (var_add_x), de
			pop hl			; y
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_add_y), de
			ld hl, 0
			ld (var_add_add), hl
			ld (p_add_rs), sp
			ld sp, p_add
			jp ntc_xn
p_add_r:		; end of add
			ld sp, (p_add_rs)
			jp ntc_xn
p_twice_c:		; call twice (normal)
			pop hl			; v
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_twice_v), de
			ld hl, 0
			ld (var_twice_twice), hl
			ld (p_twice_rs), sp
